/**
 * Board-LAN DHCP status for the Boards page: does this board's address come from a
 * star-dhcp reservation, and when did it last complete a DHCP handshake?
 *
 * Read from what dnsmasq itself uses, not from config.toml: the served reservation
 * table (/etc/star-dhcp/star-dhcp.hosts, generated by deploy/dhcp) and the DHCPACK
 * lines `log-dhcp` writes to the star-dhcp journal. The config can disagree with what
 * is being served -- on 2026-09-26 the installer read a config.toml with no `mac =`
 * lines and served zero reservations while every profile listed eight.
 *
 * Why the handshake time and not just "has a reservation": a board whose DHCP request
 * goes unanswered falls back to the static 192.168.2.<BOARD_ID>, which is the same
 * address. It answers ping and streams data exactly as if DHCP had worked. The only
 * evidence that DHCP actually served it is a DHCPACK -- and a ufw rule dropping udp/67
 * produced none while everything else looked healthy.
 *
 * Both sources are world-readable, so the backend needs no privileges. When star-dhcp
 * is not installed (no hosts file) every board reports `dhcp: undefined` and the page
 * hides the row.
 */
import { execFile } from 'node:child_process';
import fs from 'node:fs';
import type { BoardDhcpStatus } from '../../shared/types.js';

const HOSTS_PATH = process.env.STAR_DHCP_HOSTS ?? '/etc/star-dhcp/star-dhcp.hosts';
const DHCP_UNIT = process.env.STAR_DHCP_UNIT ?? 'star-dhcp';
const SYNC_UNIT = process.env.STAR_DHCP_SYNC_UNIT ?? 'star-dhcp-sync';
const REFRESH_MS = 5000;
/** How many recent DHCPACK lines to scan; each board handshakes once per boot. */
const ACK_LINES = 500;

export interface Reservation { mac: string; hostname: string }
export interface Ack { ip: string; atMs: number }

/** `<mac>,<ip>,<hostname>,<lease>` per line (dnsmasq dhcp-hostsfile), keyed by IP. */
export function parseHosts(text: string): Map<string, Reservation> {
  const out = new Map<string, Reservation>();
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const [mac, ip, hostname] = line.split(',').map((s) => s.trim());
    if (!mac || !ip) continue;
    out.set(ip, { mac: mac.toLowerCase(), hostname: hostname ?? '' });
  }
  return out;
}

const ACK_RE = /^(\d+(?:\.\d+)?)\s.*\bDHCPACK\([^)]*\)\s+(\d+\.\d+\.\d+\.\d+)\s+([0-9a-fA-F:]{17})\b/;

/**
 * `journalctl -o short-unix` lines, e.g.
 * `1790468597.123456 star-rfs dnsmasq-dhcp[1]: 797 DHCPACK(enp4s0) 192.168.2.31 4a:27:… rtd-board`.
 * Returns the latest ACK per MAC.
 */
export function parseAcks(text: string): Map<string, Ack> {
  const out = new Map<string, Ack>();
  for (const line of text.split('\n')) {
    const m = ACK_RE.exec(line);
    if (!m) continue;
    const atMs = Math.round(parseFloat(m[1]) * 1000);
    const mac = m[3].toLowerCase();
    const prev = out.get(mac);
    if (!prev || atMs >= prev.atMs) out.set(mac, { ip: m[2], atMs });
  }
  return out;
}

/**
 * The generator's refusal from `journalctl -u star-dhcp-sync -o cat`, if the
 * latest run failed: its last `error:` line. Undefined when the latest run
 * succeeded (a "wrote ..." line after the last error).
 */
export function parseSyncError(journal: string): string | undefined {
  let err: string | undefined;
  for (const raw of journal.split('\n')) {
    const line = raw.trim();
    if (line.startsWith('error: ')) err = line.slice('error: '.length);
    else if (line.startsWith('wrote ')) err = undefined;
  }
  return err;
}

export function dhcpStatusFor(
  ip: string, hosts: Map<string, Reservation>, acks: Map<string, Ack>,
): BoardDhcpStatus {
  const res = hosts.get(ip);
  if (!res) return { reserved: false };
  const ack = acks.get(res.mac);
  return {
    reserved: true,
    mac: res.mac,
    hostname: res.hostname,
    lastAckMs: ack?.atMs,
    lastAckIp: ack?.ip,
  };
}

let hosts: Map<string, Reservation> | null = null;
let acks = new Map<string, Ack>();
let syncError: string | undefined;
let timer: NodeJS.Timeout | null = null;

function refresh(): void {
  try {
    hosts = parseHosts(fs.readFileSync(HOSTS_PATH, 'utf8'));
  } catch {
    hosts = null; // star-dhcp not installed here
    return;
  }
  execFile(
    'journalctl',
    ['-u', DHCP_UNIT, '-g', 'DHCPACK', '-n', String(ACK_LINES), '-o', 'short-unix', '--no-pager', '-q'],
    { timeout: 3000, maxBuffer: 1024 * 1024 },
    (_err, stdout) => {
      // journalctl exits 1 when nothing matches; the output is still authoritative.
      if (typeof stdout === 'string') acks = parseAcks(stdout);
    },
  );
  // star-dhcp-sync regenerates the reservations whenever config.toml changes;
  // a config it refused leaves them stale, which the page should say.
  execFile(
    'journalctl',
    ['-u', SYNC_UNIT, '-n', '40', '-o', 'cat', '--no-pager', '-q'],
    { timeout: 3000, maxBuffer: 256 * 1024 },
    (_err, stdout) => {
      if (typeof stdout === 'string') syncError = parseSyncError(stdout);
    },
  );
}

export function startDhcpStatusPoller(): void {
  if (timer) return;
  refresh();
  timer = setInterval(refresh, REFRESH_MS);
  timer.unref();
}

/** Undefined when star-dhcp is not installed on this host. */
export function getBoardDhcpStatus(ip: string): BoardDhcpStatus | undefined {
  if (!hosts) return undefined;
  const s = dhcpStatusFor(ip, hosts, acks);
  return syncError ? { ...s, syncError } : s;
}
